import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();

  // plane size – use the image aspect ratio (512 × 320 → 1.6 : 1)
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // basic material – no lighting required for static composition
  const material = new MeshBasicNodeMaterial({ map: null, transparent: true });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // async texture load (function stays synchronous)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // placeholder for event handlers (none for this node)
  root.userData.handlers = {};

  // cleanup disposes resources and kills any GSAP timelines
  root.userData.cleanup = () => {
    // dispose material and geometry
    material.dispose();
    geometry.dispose();
    // kill any timelines that might have been created (none here)
    gsap.globalTimeline.clear();
  };

  return root;
}
